import QRCode from 'qrcode';
import fontUrl from './manrope-pdf.ttf?url';
import {esc as e,money,day,time,fullDate,localDate,icon as i,empty,routeArt} from './ui.js';
import './style.css';
const native=location.protocol==='capacitor:'||(location.hostname==='localhost'&&location.protocol==='https:'),base=native?'https://sync.print-station.tech':'';
const read=(key,fallback,storage=localStorage)=>{try{return JSON.parse(storage.getItem('yv:'+key))??fallback}catch{return fallback}};
const write=(key,value,storage=localStorage)=>storage.setItem('yv:'+key,JSON.stringify(value));
let token=read('token','')||read('token','',sessionStorage),me=read('profile',null),cfg=read('config',null),connected=false,booting=true;
let page='home',trips=[],orders=[],people=[],favourites=[],requests=[],selected=null,selectedSeat=null,draft={},resultsLoaded=false,filterClass='all',sort='departure',ticketFilter='upcoming',servicesTab='agencies';
let criteria={origin:'',destination:'',date:localDate(),category:'adult'},loading=false,authReturn=false,remember=!!read('token',''),requestOrder='',drawer=null;
const root=document.querySelector('#app'),noticeHost=document.querySelector('#notice');
const uid=()=>crypto.randomUUID(),ownedKey=()=>me?.id||'guest';
const storedTickets=()=>me?read('tickets:'+ownedKey(),[]):[];
const recent=()=>read('recent',[]);
let menuVersion=0,paymentTimer=null;
function notify(message,error=false){noticeHost.innerHTML=`${i(error?'help':'check',20)}<span>${e(message)}</span>`;noticeHost.className='show'+(error?' error':'');clearTimeout(notify.timer);notify.timer=setTimeout(()=>noticeHost.className='',6000)}
async function api(path,body,method=body===undefined?'GET':'POST'){
 if(!navigator.onLine)throw Error('Vous êtes hors connexion. Vos billets enregistrés restent accessibles dans Mes voyages.');
 const oldToken=token,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);let response;
 try{response=await fetch(base+'/api/v2/passenger'+path,{method,signal:controller.signal,headers:{'Content-Type':'application/json',...(oldToken?{Authorization:'Bearer '+oldToken}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})})}catch{throw Error('La connexion n’a pas abouti. Actualisez vos commandes avant de recommencer un paiement.')}finally{clearTimeout(timer)}
 if(oldToken!==token)throw Error('Votre session a changé. Recommencez.');
 const data=await response.json().catch(()=>({detail:'Réponse du serveur illisible.'}));
 if(!response.ok){if(response.status===401){clearSession();render()}const error=Error(response.status===404&&path==='/config'?'Le service voyageurs attend la mise à jour du serveur.':typeof data.detail==='string'?data.detail:'Vérifiez les informations du formulaire.');error.status=response.status;throw error}return data;
}
function clearSession(){if(me)localStorage.removeItem('yv:tickets:'+ownedKey());token='';me=null;people=[];orders=[];requests=[];favourites=[];for(const store of [localStorage,sessionStorage]){store.removeItem('yv:token');store.removeItem('yv:profile')}localStorage.removeItem('yv:pending-order')}
async function run(button,fn){if(button?.disabled)return;const text=button?.innerHTML;if(button){button.disabled=true;button.innerHTML=`<span class="spinner"></span> Un instant…`}try{return await fn()}catch(err){notify(err.message,true)}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=text}}}
function top(title=''){const count=requests.filter(x=>x.reply).length;return `<header class="topbar"><button class="brand" data-go="home" aria-label="Accueil YAM TRANS"><span class="brand-emblem"><img src="./yamtrans-logo.jpg" alt=""></span><span>YAM<span class="brand-green">TRANS</span><small>VOYAGEURS</small></span></button><div class="desktop-title">${e(title||'Le plaisir de prendre la route.')}</div><div class="header-actions"><button class="icon-button notification" data-go="requests" aria-label="Mes demandes${count?', '+count+' réponse(s)':''}">${i('bell')}${count?'<span class="notification-dot"></span>':''}</button><button class="avatar" data-go="account" aria-label="Mon compte">${me?e(me.name.charAt(0).toUpperCase()):i('user',19)}</button></div></header>`}
const navigation=[['home','home','Accueil'],['search','search','Réserver'],['tickets','ticket','Mes voyages'],['services','grid','Services'],['account','user','Compte']];
function shell(content,title=''){
 clearInterval(paymentTimer);menuVersion++;document.body.classList.remove('modal-open');root.innerHTML=`<aside class="desktop-sidebar"><div class="side-wordmark">YAM<span>TRANS</span><small>VOTRE COMPAGNON DE VOYAGE</small></div><nav>${navigation.map(([id,ico,label])=>`<button data-go="${id}" class="${page===id?'active':''}">${i(ico)}${label}${i('chevron',16)}</button>`).join('')}</nav><div class="side-bottom"><span class="tiny-label">UNE QUESTION ?</span><p>On vous accompagne.</p><button data-go="help">Contacter la compagnie ${i('arrow',18)}</button><small>Voyageurs · 1.1.0</small></div></aside><div class="app-body">${top(title)}${!navigator.onLine?`<div class="connection-banner offline">${i('wifi',17)} Mode hors connexion · billets enregistrés disponibles</div>`:!connected&&!booting?`<div class="connection-banner">${i('help',17)}<span>Le service n’est pas joignable. Vérifiez votre connexion ou la mise à jour du serveur.</span><button id="retryConnection">Réessayer</button></div>`:''}<main id="main">${content}</main><nav class="bottom-nav" aria-label="Navigation principale">${navigation.map(([id,ico,label])=>`<button data-go="${id}" class="${page===id?'active':''}" aria-current="${page===id?'page':'false'}">${i(ico,22)}<span>${label}</span></button>`).join('')}</nav></div><div id="drawerHost"></div>`;
 root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelector('#retryConnection')?.addEventListener('click',()=>start());
}
async function go(next){if(next==='tracking'){servicesTab='tracking';next='services'}if(next==='agencies'){servicesTab='agencies';next='services'}drawer=null;page=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});if(next==='tickets'&&token&&navigator.onLine)await loadOrders();if(['account','people','requests','favourites'].includes(next)&&token&&navigator.onLine)await accountData()}
function render(){if(page==='home')home();else if(page==='search')searchPage();else if(page==='seats')seatPage();else if(page==='checkout')checkout();else if(page==='tickets')ticketsPage();else if(page==='account')accountPage();else if(page==='people')peoplePage();else if(page==='requests')requestsPage();else if(page==='favourites')favouritesPage();else if(page==='services')servicesPage();else helpPage()}
function title(kicker,heading,copy=''){return `<div class="page-heading"><span class="eyebrow">${e(kicker)}</span><h1>${e(heading)}</h1>${copy?`<p>${e(copy)}</p>`:''}</div>`}
function cities(selected){return (cfg?.cities||[]).map(c=>`<option value="${e(c)}" ${c===selected?'selected':''}>${e(c)}</option>`).join('')}
function searchForm(compact=false){return `<form id="searchForm" class="search-form ${compact?'compact':''}"><div class="location-fields"><label><span>${i('pin',17)} DÉPART</span><select name="origin" required><option value="">D’où partez-vous ?</option>${cities(criteria.origin)}</select></label><button type="button" id="swap" class="swap" aria-label="Inverser le trajet">${i('swap',18)}</button><label><span>${i('pin',17)} ARRIVÉE</span><select name="destination" required><option value="">Où allez-vous ?</option>${cities(criteria.destination)}</select></label></div><div class="search-date-row"><label><span>${i('calendar',17)} DATE DU VOYAGE</span><input name="date" type="date" value="${e(criteria.date)}" min="${localDate()}" required></label><label class="category-field"><span>${i('user',17)} VOYAGEUR</span><select name="category"><option value="adult" ${criteria.category==='adult'?'selected':''}>Adulte</option><option value="child" ${criteria.category==='child'?'selected':''}>Enfant</option></select></label></div><button class="primary search-submit" ${booting||!cfg?'disabled':''}>${i('search',20)} Trouver mon départ ${i('arrow',19)}</button></form>`}
function bindSearch(){const f=document.querySelector('#searchForm');if(!f)return;document.querySelector('#swap').onclick=()=>{criteria=Object.fromEntries(new FormData(f));[criteria.origin,criteria.destination]=[criteria.destination,criteria.origin];render()};f.onsubmit=ev=>{ev.preventDefault();criteria=Object.fromEntries(new FormData(f));run(ev.submitter,doSearch)}}
async function doSearch(){if(criteria.origin===criteria.destination)throw Error('Choisissez une ville de départ et une ville d’arrivée différentes.');loading=true;page='search';render();try{trips=(await api('/trips?'+new URLSearchParams(criteria))).trips;resultsLoaded=true;let items=recent().filter(x=>x.origin!==criteria.origin||x.destination!==criteria.destination);write('recent',[{origin:criteria.origin,destination:criteria.destination},...items].slice(0,4))}finally{loading=false;render()}}
const isFav=(a,b)=>favourites.some(x=>x.origin===a&&x.destination===b);
function routeCard(route,index=0){return `<article class="route-card">${routeArt(index)}<button class="favourite-button ${isFav(route.origin,route.destination)?'on':''}" data-favourite="${index}" data-origin="${e(route.origin)}" data-destination="${e(route.destination)}" aria-label="${isFav(route.origin,route.destination)?'Retirer des':'Ajouter aux'} favoris">${i('heart',18)}</button><span class="tiny-label">${route.departures?route.departures+' départ(s) programmé(s)':'VOTRE TRAJET'}</span><h3>${e(route.origin)}<span>${i('arrow',18)} ${e(route.destination)}</span></h3><div class="route-card-bottom">${route.fare?`<div><small>À partir de</small><b>${money(route.fare)} <span>CFA</span></b></div>`:'<small>Voir les prochains départs</small>'}<button data-route="${e(route.origin)}" data-to="${e(route.destination)}" class="round-button" aria-label="Rechercher ${e(route.origin)} vers ${e(route.destination)}">${i('arrow',20)}</button></div></article>`}
function bindRoutes(){root.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{criteria={...criteria,origin:b.dataset.route,destination:b.dataset.to,date:localDate()};page='search';render();run(null,doSearch)});root.querySelectorAll('[data-favourite]').forEach(b=>b.onclick=()=>toggleFavourite(b.dataset.origin,b.dataset.destination,b))}
async function toggleFavourite(origin,destination,b){if(!token){notify('Connectez-vous pour retrouver vos favoris sur vos appareils.');authReturn=false;page='account';accountPage();return}await run(b,async()=>{favourites=(await api('/favourites',{origin,destination})).favourites;render()})}
function home(){const upcoming=orders.find(o=>o.ticket&&!['Annulé','Remboursé'].includes(o.ticket.status)&&new Date(o.departureAt)>new Date());shell(`<section class="welcome-row"><div><span class="eyebrow">${me?'HEUREUX DE VOUS RETROUVER':'BIENVENUE CHEZ YAM TRANS'}</span><h1>${me?'Bonjour, '+e(me.name.split(' ')[0])+'.':'La route vous attend.'}</h1></div><span class="greeting-symbol">${i('bus',25)}</span></section><div class="home-layout"><div><section class="hero"><span class="hero-badge"><span></span> VOYAGEZ À VOTRE RYTHME</span><h2>Votre prochaine<br>escale commence ici<span>.</span></h2><p>Le bon départ. La bonne place.<br>Votre billet, toujours avec vous.</p><div class="hero-route">${routeArt(1)}<div class="hero-bus">${i('bus',65)}<span>YAM TRANS</span></div></div></section><section class="booking-card"><div class="card-heading"><span class="square-icon">${i('search',22)}</span><div><h2>On part où ?</h2><p>Un aller simple, en quelques étapes.</p></div></div>${searchForm()}</section></div><aside class="home-side">${upcoming?`<section class="next-trip panel"><span class="eyebrow">VOTRE PROCHAIN VOYAGE</span><h3>${e(upcoming.boardingPoint)} ${i('arrow',18)} ${e(upcoming.dropPoint)}</h3><p>${day(upcoming.departureAt)} · ${time(upcoming.departureAt)}</p><button class="primary" data-open-order="${e(upcoming.id)}">Afficher mon billet ${i('ticket',18)}</button></section>`:''}<div class="quick-actions">${[['tickets','ticket','Mes billets','Votre QR en un geste'],['tracking','parcel','Suivre un colis','L’avancée de votre envoi'],['people','user','Mes voyageurs','Réservez plus vite']].map(([id,ico,t,d])=>`<button class="quick-action" data-go="${id}"><span class="square-icon soft">${i(ico,22)}</span><span><b>${t}</b><small>${d}</small></span>${i('chevron',17)}</button>`).join('')}</div><section class="assurance"><span>${i('shield',23)}</span><div><b>Votre place, en confiance.</b><p>Tarif confirmé par la compagnie et billet émis après validation du paiement.</p></div></section></aside></div>${recent().length?`<section class="recent-section"><div class="section-title"><h2>Vos dernières recherches</h2></div><div class="recent-row">${recent().map(r=>`<button data-route="${e(r.origin)}" data-to="${e(r.destination)}">${i('clock',16)} ${e(r.origin)} ${i('arrow',14)} ${e(r.destination)}</button>`).join('')}</div></section>`:''}<section class="network-section"><div class="section-title"><div><span class="eyebrow">ENVIE DE PRENDRE LA ROUTE ?</span><h2>Explorez notre réseau</h2></div><button class="text-button" data-go="search">Tous les départs ${i('arrow',17)}</button></div><div class="route-cards">${cfg?.routes?.length?cfg.routes.slice(0,3).map(routeCard).join(''):empty('bus',booting?'Connexion à la compagnie…':'Les départs arrivent ici',connected?'L’équipe n’a pas encore publié de départ disponible.':'Les lignes et tarifs réels s’affichent dès que le service est connecté.')}</div></section>`, 'Accueil');bindSearch();bindRoutes();bindOrderButtons()}
function searchPage(){let list=trips.map((t,index)=>({...t,_index:index,availableSeats:t.seats.filter(s=>s.available&&(filterClass==='all'||s.class===filterClass))})).filter(t=>t.availableSeats.length);if(sort==='price')list.sort((a,b)=>Math.min(...a.availableSeats.map(s=>s.fare))-Math.min(...b.availableSeats.map(s=>s.fare)));else list.sort((a,b)=>a.departureAt.localeCompare(b.departureAt));shell(`${title('RÉSERVEZ VOTRE VOYAGE','À chaque destination, son départ.')}<section class="panel search-panel">${searchForm(true)}</section><div class="search-shortcuts">${[0,1,2].map(n=>`<button data-date="${localDate(n)}" class="${criteria.date===localDate(n)?'selected':''}">${n===0?'Aujourd’hui':n===1?'Demain':day(localDate(n)+'T12:00:00')}</button>`).join('')}</div>${loading?'<div class="loading-state"><span class="spinner"></span> Recherche des places disponibles…</div>':resultsLoaded?`<div class="result-toolbar"><div><h2>${list.length} départ${list.length>1?'s':''}</h2><p>${e(criteria.origin)} → ${e(criteria.destination)} · ${day(criteria.date+'T12:00:00')}</p></div><button class="icon-button" id="saveRoute" aria-label="Enregistrer le trajet favori">${i('heart')}</button></div><div class="filters"><label><span>Classe</span><select id="classFilter"><option value="all">Toutes les places</option><option value="Simple" ${filterClass==='Simple'?'selected':''}>Simple</option><option value="VIP" ${filterClass==='VIP'?'selected':''}>VIP</option></select></label><label><span>Trier par</span><select id="sortFilter"><option value="departure">Heure de départ</option><option value="price" ${sort==='price'?'selected':''}>Prix croissant</option></select></label></div><section class="departures">${list.length?list.map(t=>`<article class="departure-card"><div class="departure-brand"><span class="square-icon soft">${i('bus')}</span><div><b>${e(t.bus||cfg.company)}</b><small>Voyage ${criteria.category==='child'?'enfant':'adulte'} · ${t.availableSeats.length} place(s)</small></div><span class="pill green">Places disponibles</span></div><div class="departure-route"><div><strong>${time(t.departureAt)}</strong><span>${e(t.boardingPoint)}</span></div><div class="route-line"><span></span><b>${i('bus',18)}</b><span></span></div><div><strong>${e(t.dropPoint)}</strong><span>${Math.max(0,(t.stops?.length||2)-2)} arrêt(s) intermédiaire(s)</span></div></div><div class="departure-bottom"><div><small>À partir de</small><b>${money(Math.min(...t.availableSeats.map(s=>s.fare)))} <span>CFA</span></b></div><button class="primary" data-trip="${t._index}">Choisir ${i('arrow',18)}</button></div></article>`).join(''):empty('search','Aucun départ pour ces critères','Essayez une autre date ou une autre classe de siège.')}<p class="footnote">Les disponibilités sont vérifiées au moment de réserver. Montants en francs CFA.</p></section>`:empty('search','Le prochain voyage commence ici','Indiquez vos villes et votre date pour consulter les vrais départs.')}`, 'Réserver');bindSearch();root.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{criteria.date=b.dataset.date;if(criteria.origin&&criteria.destination)run(b,doSearch);else render()});document.querySelector('#classFilter')?.addEventListener('change',ev=>{filterClass=ev.target.value;render()});document.querySelector('#sortFilter')?.addEventListener('change',ev=>{sort=ev.target.value;render()});document.querySelector('#saveRoute')?.addEventListener('click',ev=>toggleFavourite(criteria.origin,criteria.destination,ev.currentTarget));root.querySelectorAll('[data-trip]').forEach(b=>b.onclick=()=>{selected=trips[Number(b.dataset.trip)];selectedSeat=null;draft={passengerName:me?.name||'',phone:me?.phone||''};page='seats';render()})}
function steps(active){return `<ol class="booking-steps">${['Départ','Siège','Voyageur','Paiement'].map((s,index)=>`<li class="${index<=active?'done':''}"><span>${index<active?i('check',12):index+1}</span>${s}</li>`).join('')}</ol>`}
function seatPage(){if(!selected){page='search';return searchPage()}const t=selected;const seats=t.seats.filter(s=>filterClass==='all'||s.class===filterClass),positioned=seats.every(s=>Number.isInteger(Number(s.row))&&Number(s.row)>0&&Number(s.row)<=80&&Number(s.col)>0&&Number(s.col)<=4);shell(`<button class="back-button" id="backSearch">${i('back',18)} Les départs</button>${steps(1)}${title('VOTRE ESPACE À BORD','Choisissez la place qui vous ressemble.',t.boardingPoint+' → '+t.dropPoint+' · '+fullDate(t.departureAt))}<div class="booking-layout"><section class="panel seat-panel"><div class="bus-header"><span>${i('bus',22)} ${e(t.bus)}</span><span>AVANT DU BUS ${i('arrow',16)}</span></div><div class="seat-legend"><span><b></b> Libre</span><span><b class="legend-selected"></b> Votre place</span><span><b class="legend-occupied"></b> Occupé</span></div><div class="bus-body"><div class="windshield"><span>Conducteur</span>${i('seat',24)}</div><div class="seat-grid ${positioned?'positioned':''}">${seats.map(s=>`<button ${positioned?`style="grid-row:${Number(s.row)};grid-column:${Number(s.col)}" data-col="${Number(s.col)}"`:''} class="seat ${s.class==='VIP'?'vip':''} ${selectedSeat?.label===s.label?'selected':''}" data-seat="${e(s.label)}" ${s.available?'':'disabled'} aria-label="Siège ${e(s.label)}, ${e(s.class)}${s.available?', '+money(s.fare)+' CFA':', indisponible'}" aria-pressed="${selectedSeat?.label===s.label}">${i('seat',25)}<b>${e(s.label)}</b><small>${e(s.class)}</small></button>`).join('')}</div><span class="bus-rear">YAM TRANS · BON VOYAGE</span></div><details class="route-details"><summary>Voir les arrêts du voyage ${i('chevron',16)}</summary><ol>${(t.stops||[t.boardingPoint,t.dropPoint]).map(s=>`<li>${e(s)}</li>`).join('')}</ol></details></section><aside class="panel booking-summary"><span class="eyebrow">VOTRE SÉLECTION</span><h2>${e(t.boardingPoint)}<span class="block-arrow">${i('arrow',22)} ${e(t.dropPoint)}</span></h2><dl><div><dt>Départ</dt><dd>${day(t.departureAt)} · ${time(t.departureAt)}</dd></div><div><dt>Siège</dt><dd>${selectedSeat?e(selectedSeat.label)+' · '+e(selectedSeat.class):'À sélectionner'}</dd></div><div><dt>Voyageur</dt><dd>${criteria.category==='child'?'Enfant':'Adulte'}</dd></div></dl><div class="price-total"><span>Total du billet</span><b>${selectedSeat?money(selectedSeat.fare):'—'} <small>CFA</small></b></div><button id="continueSeat" class="primary wide" ${selectedSeat?'':'disabled'}>Continuer ${i('arrow',18)}</button><p class="footnote">La place sera bloquée lors de la création du paiement, pendant 15 minutes maximum.</p></aside></div>`, 'Choisir un siège');document.querySelector('#backSearch').onclick=()=>{page='search';render()};root.querySelectorAll('[data-seat]').forEach(b=>b.onclick=()=>{selectedSeat=t.seats.find(s=>s.label===b.dataset.seat);render()});document.querySelector('#continueSeat').onclick=()=>{if(!token){authReturn=true;page='account'}else page='checkout';render()}}
function checkout(){if(!selectedSeat){page='seats';return render()}if(!me){page='account';authReturn=true;return render()}const t=selected;shell(`<button class="back-button" id="backSeat">${i('back',18)} Modifier le siège</button>${steps(2)}${title('PLUS QUE QUELQUES INSTANTS','Qui prend la route ?','Les informations doivent correspondre à la pièce présentée au départ.')}<div class="booking-layout"><section class="panel"><form id="bookingForm">${people.length?`<label>Un voyageur déjà enregistré<select id="savedPerson"><option value="">Saisir un voyageur</option>${people.map(p=>`<option value="${e(p.id)}">${e(p.name)}</option>`).join('')}</select></label>`:''}<label>Nom complet<input name="passengerName" value="${e(draft.passengerName)}" autocomplete="name" minlength="2" maxlength="120" required></label><label>Téléphone<input name="phone" value="${e(draft.phone)}" autocomplete="tel" inputmode="tel" minlength="8" maxlength="30" required></label><label class="check"><input name="saveTraveller" type="checkbox"> Enregistrer ce voyageur pour mes prochaines réservations</label><div class="travel-tip">${i('help',20)}<p>Gardez votre pièce d’identité et vérifiez la gare avant le départ. Pour un enfant, confirmez les conditions d’accompagnement auprès de la compagnie.</p></div><label class="check"><input name="confirmed" type="checkbox" required> J’ai vérifié le trajet, la date et les informations du voyageur.</label><button class="primary wide" ${cfg?.paymentEnabled&&connected?'':'disabled'}>${i('lock',18)} Continuer vers le paiement ${i('arrow',18)}</button>${!cfg?.paymentEnabled?'<p class="inline-note">Le paiement en ligne attend son activation par la compagnie.</p>':''}</form></section><aside class="panel booking-summary"><span class="eyebrow">RÉCAPITULATIF</span><h2>${e(t.boardingPoint)}<span class="block-arrow">${i('arrow',20)} ${e(t.dropPoint)}</span></h2><dl><div><dt>Date</dt><dd>${day(t.departureAt)}</dd></div><div><dt>Heure</dt><dd>${time(t.departureAt)}</dd></div><div><dt>Place</dt><dd>${e(selectedSeat.label)} · ${e(selectedSeat.class)}</dd></div><div><dt>Catégorie</dt><dd>${criteria.category==='child'?'Enfant':'Adulte'}</dd></div></dl><div class="price-total"><span>Total à payer</span><b>${money(selectedSeat.fare)} <small>CFA</small></b></div><div class="payment-brand"><span>${i('shield',24)}</span><div><b>Paiement par YengaPay</b><small>Vous choisissez votre moyen de paiement sur la page sécurisée.</small></div></div></aside></div>`, 'Voyageur et paiement');document.querySelector('#backSeat').onclick=()=>{page='seats';render()};document.querySelector('#savedPerson')?.addEventListener('change',ev=>{const p=people.find(p=>p.id===ev.target.value);if(p){document.querySelector('[name=passengerName]').value=p.name;document.querySelector('[name=phone]').value=p.phone}});const f=document.querySelector('#bookingForm');f.addEventListener('input',()=>{const d=Object.fromEntries(new FormData(f));draft={passengerName:d.passengerName,phone:d.phone}});f.onsubmit=ev=>{ev.preventDefault();run(ev.submitter,async()=>{const d=Object.fromEntries(new FormData(f));const body={tripId:t.id,seat:selectedSeat.label,boardingPoint:t.boardingPoint,dropPoint:t.dropPoint,passengerCategory:criteria.category,passengerName:d.passengerName,phone:d.phone};const signature=JSON.stringify(body),pending=read('pending-order',null),id=pending?.signature===signature?pending.id:uid();write('pending-order',{id,signature});if(d.saveTraveller&&!people.some(p=>p.name===d.passengerName&&p.phone===d.phone)){people=(await api('/travellers/'+id,{id,name:d.passengerName,phone:d.phone},'PUT')).travellers}let o;try{o=await api('/orders',{id,...body})}catch(err){await go('tickets');throw err}localStorage.removeItem('yv:pending-order');orders=[o,...orders.filter(x=>x.id!==o.id)];page='tickets';render();openOrder(o.id)})}}
async function loadOrders(){const snapshot=token;try{const data=await api('/orders');if(snapshot!==token)return;orders=data.orders;if(me&&storedTickets().length)write('tickets:'+ownedKey(),storedTickets().map(saved=>orders.find(o=>o.id===saved.id)||saved));if(page==='tickets')render()}catch(err){notify(err.message,true)}}
function orderBad(o){return ['Annulé','Remboursé'].includes(o.ticket?.status)}
function ticketsPage(){const saved=storedTickets(),list=token?(navigator.onLine?orders:orders.length?orders:saved):[];let visible=list.filter(o=>ticketFilter==='all'||ticketFilter==='saved'?ticketFilter!=='saved'||saved.some(s=>s.id===o.id):ticketFilter==='upcoming'?new Date(o.departureAt)>=new Date()&&!orderBad(o):new Date(o.departureAt)<new Date()||orderBad(o));shell(`${title('VOTRE CARNET DE ROUTE','Mes voyages','Vos billets, vos paiements et les détails de vos départs.')}<div class="tabs">${[['upcoming','À venir'],['past','Passés'],['saved','Hors ligne'],['all','Tous']].map(([id,label])=>`<button data-ticket-filter="${id}" class="${ticketFilter===id?'selected':''}">${label}${id==='saved'?' '+i('download',14):''}</button>`).join('')}</div>${!token?empty('ticket','Votre prochain voyage vous attend','Connectez-vous pour retrouver vos commandes et billets.', '<button class="primary" data-go="account">Me connecter '+i('arrow',18)+'</button>'):`<div class="section-title"><p>${visible.length} voyage(s) ${navigator.onLine?'':'enregistré(s)'}</p><button class="text-button" id="refreshOrders">${i('refresh',17)} Actualiser</button></div><div class="ticket-list">${visible.length?visible.map(o=>`<article class="travel-card ${orderBad(o)?'cancelled':''}"><div class="travel-card-header"><span class="pill ${o.ticket&&!orderBad(o)?'green':'amber'}">${e(orderBad(o)?o.ticket.status:o.ticket?'Billet confirmé':o.status)}</span><small>${day(o.departureAt)}</small></div><div class="travel-route"><div><strong>${time(o.departureAt)}</strong><small>${e(o.boardingPoint)}</small></div><div class="route-line">${i('bus',21)}</div><div><strong>${e(o.dropPoint)}</strong><small>${e(o.passengerName)}</small></div></div><div class="travel-card-bottom"><span>${i('seat',18)} Siège ${e(o.seat)}</span><button data-open-order="${e(o.id)}" class="text-button">${o.ticket?'Voir mon billet':'Ouvrir la commande'} ${i('chevron',18)}</button></div></article>`).join(''):empty('ticket','Rien ici pour le moment',ticketFilter==='saved'?'Enregistrez un billet depuis son détail pour le retrouver sans Internet.':'Choisissez votre prochain départ et retrouvez-le ici.', '<button class="primary" data-go="search">Réserver un voyage</button>')}</div>`}`, 'Mes voyages');root.querySelectorAll('[data-ticket-filter]').forEach(b=>b.onclick=()=>{ticketFilter=b.dataset.ticketFilter;render()});document.querySelector('#refreshOrders')?.addEventListener('click',ev=>run(ev.currentTarget,loadOrders));bindOrderButtons()}
function bindOrderButtons(){root.querySelectorAll('[data-open-order]').forEach(b=>b.onclick=()=>openOrder(b.dataset.openOrder))}
function modal(html,large=false){clearInterval(paymentTimer);const host=document.querySelector('#drawerHost');host.innerHTML=`<div class="drawer-backdrop"><section role="dialog" aria-modal="true" class="drawer ${large?'large':''}" tabindex="-1"><button class="drawer-close icon-button" aria-label="Fermer">${i('close')}</button>${html}</section></div>`;drawer=host.querySelector('.drawer');drawer.focus();const close=()=>{clearInterval(paymentTimer);host.innerHTML='';drawer=null;document.body.classList.remove('modal-open')};document.body.classList.add('modal-open');host.querySelector('.drawer-close').onclick=close;host.querySelector('.drawer-backdrop').onclick=ev=>{if(ev.target===ev.currentTarget)close()};drawer.onkeydown=ev=>{if(ev.key==='Escape')close();if(ev.key==='Tab'){const all=[...drawer.querySelectorAll('button:not([disabled]),a,input,select,textarea')];const first=all[0],last=all.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}};return close}
function openOrder(id){const o=[...orders,...storedTickets()].find(x=>x.id===id);if(!o)return;const cancelled=orderBad(o),saved=storedTickets().some(x=>x.id===o.id);modal(`<div class="ticket-pass"><div class="pass-brand">YAM<span>TRANS</span><small>${o.ticket?'VOTRE BILLET DE VOYAGE':'VOTRE COMMANDE'}</small></div><span class="pill ${o.ticket&&!cancelled?'green':'amber'}">${e(cancelled?o.ticket.status:o.status)}</span><h2>${e(o.boardingPoint)}<span>${i('arrow',22)} ${e(o.dropPoint)}</span></h2><div class="pass-main-details"><div><small>DÉPART</small><b>${day(o.departureAt)}</b><strong>${time(o.departureAt)}</strong></div><div><small>SIÈGE</small><strong>${e(o.seat)}</strong><b>${e(o.ticket?.seatClass||'')}</b></div></div><div class="perforation"></div>${o.ticket?`<div class="qr-area"><canvas id="ticketQr"></canvas><p>${e(o.ticket.pnr)}</p><span>${cancelled?'Billet annulé ou remboursé':o.ticket.boarded?'Embarquement enregistré':'Présentez ce QR et votre pièce au départ.'}</span></div>`:`<div class="payment-pending">${i('lock',32)}<h3>Finalisez votre paiement</h3><p>Votre place est bloquée au plus tard jusqu’à ${time(o.expiresAt)}. Le billet apparaît après confirmation.</p>${o.checkoutUrl&&new Date(o.expiresAt)>new Date()?`<a class="primary wide" href="${e(o.checkoutUrl)}" target="_blank" rel="noopener noreferrer" id="openYenga">Ouvrir YengaPay ${i('arrow',18)}</a>`:''}<button class="secondary wide" id="verifyOrder">${i('refresh',18)} Vérifier le paiement</button></div>`}<dl class="pass-dl"><div><dt>Voyageur</dt><dd>${e(o.passengerName)}</dd></div><div><dt>Téléphone</dt><dd>${e(o.phone)}</dd></div><div><dt>Montant</dt><dd>${money(o.amount)} CFA</dd></div><div><dt>Voyage</dt><dd>${e(o.tripStatus||'Voir avec la compagnie')}</dd></div></dl>${o.message?`<p class="inline-note">${e(o.message)}</p>`:''}<small class="reference">Référence ${e(o.id)}</small></div><div class="pass-actions">${o.trackingUrl&&safeMap(o.trackingUrl)?`<a class="secondary" href="${e(o.trackingUrl)}" target="_blank" rel="noopener noreferrer">${i('pin',18)} Suivre mon car</a>`:''}${o.ticket?`<button id="offlineTicket" class="${saved?'saved':'secondary'}">${i('download',18)} ${saved?'Enregistré hors ligne':'Garder hors ligne'}</button><button id="downloadTicket" class="secondary">${i('ticket',18)} Billet PDF</button><button id="calendarTicket" class="secondary">${i('calendar',18)} Mon calendrier</button>`:''}<button class="secondary" id="requestChange">${i('help',18)} Une demande pour ce voyage</button></div><p class="footnote">${!navigator.onLine?'Dernière version enregistrée. Actualisez le statut avant de voyager.':'Modifications et remboursements sont soumis à la validation de la compagnie.'}</p>`,true);
 if(!o.ticket&&o.checkoutUrl&&o.status==='En attente du paiement')paymentTimer=setInterval(async()=>{if(document.hidden||!navigator.onLine)return;try{const updated=await api('/orders/'+encodeURIComponent(o.id)+'/verify',{});orders=orders.map(x=>x.id===o.id?updated:x);if(updated.ticket||updated.status!==o.status){openOrder(o.id);if(updated.ticket)notify('Paiement confirmé. Votre billet est prêt.')}}catch{}},15000);
 if(o.ticket)QRCode.toCanvas(document.querySelector('#ticketQr'),o.ticket.pnr,{width:210,margin:2,errorCorrectionLevel:'M'}).catch(()=>notify('QR indisponible. Utilisez la référence du billet.',true));document.querySelector('#verifyOrder')?.addEventListener('click',ev=>run(ev.currentTarget,async()=>{const updated=await api('/orders/'+encodeURIComponent(o.id)+'/verify',{});orders=orders.map(x=>x.id===o.id?updated:x);openOrder(o.id);notify(updated.ticket?'Votre billet est confirmé.':updated.message||'Le paiement n’est pas encore confirmé.')}));document.querySelector('#offlineTicket')?.addEventListener('click',()=>{write('tickets:'+ownedKey(),[o,...storedTickets().filter(x=>x.id!==o.id)].slice(0,30));openOrder(o.id);notify('Billet enregistré sur cet appareil. Il reste disponible sans Internet.')});document.querySelector('#downloadTicket')?.addEventListener('click',ev=>run(ev.currentTarget,()=>exportPdf(o)));document.querySelector('#calendarTicket')?.addEventListener('click',()=>calendar(o));document.querySelector('#requestChange').onclick=()=>{document.body.classList.remove('modal-open');requestOrder=o.id;page='requests';render();requestModal()}}
async function shareOrDownload(blob,name){const file=new File([blob],name,{type:blob.type});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Mon voyage YAM TRANS'});return}catch(err){if(err.name==='AbortError')return}}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)}
async function exportPdf(o){
 const {jsPDF}=await import('jspdf');
 const lines=[o.boardingPoint+' → '+o.dropPoint,fullDate(o.departureAt),o.passengerName,'Siège '+o.seat+' · '+o.ticket.seatClass,money(o.amount)+' CFA','Statut : '+o.ticket.status];
 let pdf=new jsPDF({unit:'mm',format:[100,210]}),font=null;
 try{const response=await fetch(fontUrl);if(response.ok){const bytes=new Uint8Array(await response.arrayBuffer());let binary='';for(let n=0;n<bytes.length;n+=8192)binary+=String.fromCharCode(...bytes.subarray(n,n+8192));font=btoa(binary);pdf.addFileToVFS('Manrope.ttf',font);pdf.addFont('Manrope.ttf','Manrope','normal');pdf.setFont('Manrope')}}catch{}
 const safe=value=>font?value:String(value).normalize('NFKD').replace(/\p{M}/gu,'').replace(/[^\x20-\x7e]/g,' ');
 pdf.setFontSize(12);const wrapped=lines.map(line=>pdf.splitTextToSize(safe(line),80));const height=Math.max(210,70+wrapped.reduce((total,line)=>total+line.length*6+4,0)+70);
 if(height>210){pdf.addPage([100,height]);pdf.deletePage(1);if(font)pdf.setFont('Manrope')}
 pdf.setFillColor(16,46,67);pdf.rect(0,0,100,40,'F');pdf.setTextColor(255);pdf.setFontSize(20);pdf.text('YAM TRANS',10,17);pdf.setFontSize(8);pdf.text('VOTRE BILLET DE VOYAGE',10,26);pdf.setTextColor(18,42,57);pdf.setFontSize(12);let y=51;
 for(const line of wrapped){pdf.text(line,10,y);y+=line.length*6+4}
 const qr=await QRCode.toDataURL(o.ticket.pnr,{width:240,margin:1});pdf.addImage(qr,'PNG',29,y+3,42,42);pdf.setFontSize(7);pdf.text(pdf.splitTextToSize(o.ticket.pnr,85),50,y+51,{align:'center'});pdf.text(safe('Présentez votre pièce au départ.'),50,height-12,{align:'center'});await shareOrDownload(pdf.output('blob'),'YamTrans-'+o.ticket.pnr+'.pdf');
}
function calendar(o){const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,' ');const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//YamTrans//Voyageurs//FR','BEGIN:VEVENT','UID:'+o.id+'@yamtrans','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(o.departureAt),'DURATION:PT30M','SUMMARY:'+clean('Départ YAM TRANS : '+o.boardingPoint+' > '+o.dropPoint),'LOCATION:'+clean(o.boardingPoint),'DESCRIPTION:'+clean('Billet '+o.ticket.pnr+' - siège '+o.seat+'. Vérifiez la gare auprès de la compagnie.'),'END:VEVENT','END:VCALENDAR'].join('\r\n');shareOrDownload(new Blob([content],{type:'text/calendar'}),'YamTrans-voyage.ics')}
async function accountData(){const snapshot=token;const result=await Promise.allSettled([api('/travellers'),api('/favourites'),api('/requests')]);if(snapshot!==token)return;for(const [n,r]of result.entries())if(r.status==='fulfilled'){if(n===0)people=r.value.travellers;if(n===1)favourites=r.value.favourites;if(n===2)requests=r.value.requests}if(['people','requests','favourites'].includes(page))render()}
function accountPage(register=false){if(!me){shell(`${title('VOTRE ESPACE PERSONNEL',register?'Bienvenue à bord.':'Heureux de vous revoir.',authReturn?'Connectez-vous pour terminer votre réservation.':'Retrouvez vos billets et préparez vos prochains voyages.')}<div class="auth-layout"><section class="panel auth-panel"><div class="auth-switch"><button id="loginTab" class="${register?'':'selected'}">Connexion</button><button id="registerTab" class="${register?'selected':''}">Créer un compte</button></div><form id="authForm">${register?'<label>Nom complet<input name="name" autocomplete="name" minlength="2" maxlength="120" required></label><label>Téléphone<input name="phone" type="tel" autocomplete="tel" minlength="8" maxlength="30" required></label>':''}<label>Adresse e-mail<input name="email" type="email" autocomplete="email" maxlength="200" required></label><label>Mot de passe<span class="password-input"><input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="10" maxlength="200" required><button type="button" id="showPassword" aria-label="Afficher le mot de passe">${i('eye',19)}</button></span></label><p class="footnote">Au moins 10 caractères. Gardez ce mot de passe personnel.</p><label class="check"><input name="remember" type="checkbox" ${remember?'checked':''}> Rester connecté sur cet appareil personnel</label><button class="primary wide">${register?'Créer mon compte':'Me connecter'} ${i('arrow',18)}</button></form></section><aside class="auth-benefits"><span class="square-icon">${i('ticket',27)}</span><h2>Vos voyages.<br>Tout simplement.</h2>${[['ticket','Tous vos billets au même endroit'],['user','Vos voyageurs enregistrés'],['heart','Vos trajets favoris'],['download','Vos billets disponibles hors ligne']].map(([ico,t])=>`<p>${i(ico,19)}${t}</p>`).join('')}</aside></div>`, 'Mon compte');document.querySelector('#loginTab').onclick=()=>accountPage(false);document.querySelector('#registerTab').onclick=()=>accountPage(true);document.querySelector('#showPassword').onclick=()=>{const el=document.querySelector('[name=password]');el.type=el.type==='password'?'text':'password'};document.querySelector('#authForm').onsubmit=ev=>{ev.preventDefault();run(ev.submitter,async()=>{const data=Object.fromEntries(new FormData(ev.target));remember=!!data.remember;delete data.remember;const out=await api(register?'/register':'/login',data);token=out.token;me=out.profile;for(const store of [localStorage,sessionStorage])store.removeItem('yv:token');write('token',token,remember?localStorage:sessionStorage);write('profile',me,remember?localStorage:sessionStorage);await accountData();if(authReturn&&selectedSeat){authReturn=false;page='checkout';render()}else{page='account';render();loadOrders()}})};return}
 const links=[['people','user','Mes voyageurs',people.length+' voyageur(s) enregistré(s)'],['favourites','heart','Mes trajets favoris','Vos lignes, en un geste'],['requests','help','Mes demandes','Messages et réponses de la compagnie'],['agencies','pin','Nos agences','Adresses et itinéraires']];shell(`${title('MON ESPACE','Bonjour, '+me.name.split(' ')[0]+'.')}<div class="account-layout"><section class="panel profile-card"><div class="profile-avatar">${e(me.name.charAt(0))}</div><h2>${e(me.name)}</h2><p>${e(me.email)}</p><span>${e(me.phone||'Téléphone à renseigner')}</span><button class="secondary wide" id="editProfile">${i('edit',17)} Modifier mes informations</button></section><section class="account-links panel">${links.map(([id,ico,t,s])=>`<button data-go="${id}"><span class="square-icon soft">${i(ico)}</span><span><b>${t}</b><small>${e(s)}</small></span>${i('chevron',18)}</button>`).join('')}<button id="changePassword"><span class="square-icon soft">${i('lock')}</span><span><b>Changer mon mot de passe</b><small>Protéger mon compte</small></span>${i('chevron',18)}</button><button id="logout" class="logout"><span class="square-icon">${i('logout')}</span><span><b>Me déconnecter</b><small>Efface les billets enregistrés sur cet appareil</small></span></button></section></div>`, 'Mon compte');document.querySelector('#logout').onclick=ev=>run(ev.currentTarget,async()=>{if(navigator.onLine)await api('/logout',{});clearSession();page='home';render()});document.querySelector('#editProfile').onclick=()=>{const close=modal('<h2>Mes informations</h2><p class="muted">Le nom et le numéro utilisés pour vous contacter.</p><form id="profileForm"><label>Nom complet<input name="name" value="'+e(me.name)+'" minlength="2" maxlength="120" required></label><label>Téléphone<input name="phone" value="'+e(me.phone)+'" type="tel" minlength="8" maxlength="30" required></label><button class="primary wide">Enregistrer</button></form>');document.querySelector('#profileForm').onsubmit=ev=>{ev.preventDefault();run(ev.submitter,async()=>{me=await api('/me',Object.fromEntries(new FormData(ev.target)),'PUT');write('profile',me,remember?localStorage:sessionStorage);close();render();notify('Vos informations ont été mises à jour.')})}};document.querySelector('#changePassword').onclick=()=>{const close=modal('<h2>Changer mon mot de passe</h2><form id="passwordForm"><label>Mot de passe actuel<input name="currentPassword" type="password" autocomplete="current-password" minlength="10" required></label><label>Nouveau mot de passe<input name="newPassword" type="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><button class="primary wide">Enregistrer le nouveau mot de passe</button></form>');document.querySelector('#passwordForm').onsubmit=ev=>{ev.preventDefault();run(ev.submitter,async()=>{await api('/password',Object.fromEntries(new FormData(ev.target)));close();notify('Mot de passe modifié. Les autres sessions ont été fermées.')})}}}
function needAccount(){if(token)return false;page='account';accountPage();return true}
function peoplePage(){if(needAccount())return;shell(`${title('PRÉPAREZ VOS PROCHAINS DÉPARTS','Mes voyageurs','Enregistrez les personnes pour lesquelles vous réservez.')}<div class="section-title"><span>${people.length}/12 voyageurs</span><button class="primary" id="addPerson">${i('plus',18)} Ajouter</button></div><div class="people-grid">${people.length?people.map(p=>`<article class="panel person-card"><div class="person-avatar">${e(p.name.charAt(0))}</div><h3>${e(p.name)}</h3><p>${e(p.phone||'Téléphone non renseigné')}</p>${p.birthDate?'<small>Naissance : '+e(p.birthDate)+'</small>':''}<div><button class="text-button" data-edit-person="${e(p.id)}">${i('edit',16)} Modifier</button><button class="text-button danger" data-delete-person="${e(p.id)}">Retirer</button></div></article>`).join(''):empty('user','Les bonnes personnes, prêtes à partir','Ajoutez un proche pour remplir plus vite ses prochaines réservations.')}</div>`, 'Mes voyageurs');document.querySelector('#addPerson').onclick=()=>personModal();root.querySelectorAll('[data-edit-person]').forEach(b=>b.onclick=()=>personModal(people.find(p=>p.id===b.dataset.editPerson)));root.querySelectorAll('[data-delete-person]').forEach(b=>b.onclick=()=>{const close=modal(`<h2>Retirer ce voyageur ?</h2><p>Ses billets existants seront conservés. Vous pourrez l’ajouter de nouveau.</p><button id="confirmDeletePerson" class="primary wide">Retirer le voyageur</button>`);document.querySelector('#confirmDeletePerson').onclick=ev=>run(ev.currentTarget,async()=>{people=(await api('/travellers/'+encodeURIComponent(b.dataset.deletePerson),undefined,'DELETE')).travellers;close();render()})})}
function personModal(p={}){const close=modal(`<h2>${p.id?'Modifier':'Ajouter'} un voyageur</h2><form id="personForm"><label>Nom complet<input name="name" value="${e(p.name||'')}" minlength="2" maxlength="120" required></label><label>Téléphone<input name="phone" type="tel" value="${e(p.phone||'')}" maxlength="30"></label><label>Date de naissance <small>Facultative</small><input name="birthDate" type="date" value="${e(p.birthDate||'')}" max="${localDate()}" min="1900-01-01"></label><button class="primary wide">Enregistrer le voyageur</button></form>`);document.querySelector('#personForm').onsubmit=ev=>{ev.preventDefault();run(ev.submitter,async()=>{const id=p.id||uid();people=(await api('/travellers/'+id,{id,...Object.fromEntries(new FormData(ev.target))},'PUT')).travellers;close();render()})}}
function favouritesPage(){if(needAccount())return;shell(`${title('VOS LIGNES PRÉFÉRÉES','Mes trajets favoris','Retrouvez vos villes et relancez une recherche.')}<div class="route-cards">${favourites.length?favourites.map(routeCard).join(''):empty('heart','La route a ses habitudes','Touchez le cœur d’un trajet pour le retrouver ici.','<button class="primary" data-go="search">Chercher un trajet</button>')}</div>`, 'Favoris');bindRoutes()}
function requestsPage(){if(needAccount())return;shell(`${title('EN LIEN AVEC LA COMPAGNIE','Mes demandes','Une question, un changement ou un besoin particulier ?')}<div class="section-title"><span>${requests.filter(r=>r.status!=='Clôturée').length} demande(s) en cours</span><button id="newRequest" class="primary">${i('plus',18)} Nouvelle demande</button></div><div class="request-list">${requests.length?requests.slice().reverse().map(r=>`<article class="panel request-card"><div class="section-title"><span class="pill ${r.status==='Clôturée'?'green':'amber'}">${e(r.status)}</span><small>${day(r.createdAt)}</small></div><h3>${e(r.kind)}</h3><p>${e(r.message)}</p><small class="reference">${e(r.orderId?'Commande '+r.orderId:'Demande '+r.id)}</small>${r.reply?`<div class="staff-reply"><span class="eyebrow">RÉPONSE DE LA COMPAGNIE</span><p>${e(r.reply)}</p></div>`:'<div class="pending-reply">'+i('clock',16)+' En attente du retour de la compagnie</div>'}</article>`).join(''):empty('help','On reste à votre écoute','Vos échanges avec la compagnie apparaîtront ici.')}</div>`, 'Mes demandes');document.querySelector('#newRequest').onclick=requestModal}
function requestModal(){const close=modal(`<h2>Comment vous aider ?</h2><p class="muted">Une demande ne modifie pas automatiquement votre billet et ne déclenche aucun remboursement.</p><form id="requestForm"><label>Pour quel voyage ?<select name="orderId"><option value="">Question générale</option>${orders.map(o=>`<option value="${e(o.id)}" ${o.id===requestOrder?'selected':''}>${e(o.boardingPoint)} → ${e(o.dropPoint)} · ${day(o.departureAt)}</option>`).join('')}</select></label><label>Sujet<select name="kind">${['Assistance','Modification','Annulation / remboursement','Bagages','Autre'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Votre message<textarea name="message" minlength="8" maxlength="1500" rows="5" required placeholder="Expliquez votre demande à la compagnie…"></textarea></label><button class="primary wide">Envoyer la demande ${i('arrow',18)}</button></form>`);const id=uid();document.querySelector('#requestForm').onsubmit=ev=>{ev.preventDefault();run(ev.submitter,async()=>{const request=await api('/requests',{id,...Object.fromEntries(new FormData(ev.target))});requests=[...requests.filter(x=>x.id!==id),request];requestOrder='';close();render();notify('Demande transmise à la compagnie. Retrouvez sa réponse ici.')})}}
function servicesPage(){shell(`${title('BIEN PLUS QU’UN DÉPART','À vos côtés, tout au long du voyage.')}<div class="service-selector">${[['agencies','pin','Nos agences'],['tracking','parcel','Suivre un colis'],['help','help','Aide au voyage']].map(([id,ico,t])=>`<button data-service="${id}" class="${servicesTab===id?'selected':''}">${i(ico,20)}${t}</button>`).join('')}</div>${servicesTab==='agencies'?`<div class="agency-list">${cfg?.agencies?.length?cfg.agencies.map(a=>`<article class="panel agency-card"><span class="square-icon soft">${i('pin',25)}</span><div><small class="eyebrow">${e(a.city||'AGENCE YAM TRANS')}</small><h3>${e(a.name)}</h3><p>${e(a.address||'Adresse à confirmer auprès de la compagnie.')}</p>${a.pickupDirections?'<p class="muted">'+e(a.pickupDirections)+'</p>':''}<div class="agency-actions">${safeMap(a.mapsUrl)?`<a class="secondary" href="${e(a.mapsUrl)}" target="_blank" rel="noopener noreferrer">${i('pin',17)} Itinéraire</a>`:''}${a.phone?`<a class="secondary" href="tel:${e(a.phone.replace(/[^+\d]/g,''))}">${i('phone',17)} Appeler</a>`:''}</div></div></article>`).join(''):empty('pin','Vos points de départ','Les agences apparaîtront après leur publication par la compagnie.')}</div>`:servicesTab==='tracking'?`<section class="tracking-panel panel"><span class="square-icon">${i('parcel',32)}</span><h2>Où en est votre envoi ?</h2><p>Retrouvez son statut avec la référence indiquée sur votre reçu.</p><form id="trackingForm"><label>Référence de l’envoi<input name="code" maxlength="120" required placeholder="Ex. OUA-00001" autocapitalize="characters"></label><button class="primary wide">Suivre mon envoi ${i('arrow',18)}</button></form><div id="trackingResult" aria-live="polite"></div></section>`:helpContent()}`, 'Services');root.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{servicesTab=b.dataset.service;render()});document.querySelector('#trackingForm')?.addEventListener('submit',ev=>{ev.preventDefault();run(ev.submitter,async()=>{const code=new FormData(ev.target).get('code').trim().toUpperCase();const data=await api('/shipments/'+encodeURIComponent(code));document.querySelector('#trackingResult').innerHTML=`<div class="shipment-result"><span class="pill green">${e(data.status||'Enregistré')}</span><h3>${e(data.origin)} ${i('arrow',17)} ${e(data.destination)}</h3><p>Référence ${e(data.code||code)}</p>${data.updatedAt?'<small>Dernière mise à jour : '+e(fullDate(data.updatedAt))+'</small>':''}<p class="muted">Munissez-vous du reçu et des justificatifs demandés pour le retrait.</p></div>`})})}
function safeMap(url){try{const u=new URL(url);return u.protocol==='https:'}catch{return false}}
function helpContent(){return `<div class="help-grid">${[['ticket','Votre billet au départ','Présentez le QR de votre billet avec votre pièce d’identité. Gardez une copie hors connexion depuis Mes voyages.'],['bag','Bagages et accompagnement','Les limites de poids, tarifs et conditions enfants sont à confirmer auprès de la compagnie avant le départ.'],['lock','Un paiement sans billet ?','Ouvrez la commande dans Mes voyages et vérifiez le paiement. Si une assistance est demandée, évitez un second paiement et contactez la compagnie avec la référence.'],['edit','Modifier ou annuler','Ouvrez votre voyage puis « Une demande pour ce voyage ». La compagnie confirme les possibilités et les conditions avant toute modification.'],['pin','La bonne gare','Consultez Nos agences et confirmez votre point de départ. Prévoyez du temps pour l’enregistrement et les bagages.'],['wifi','Suivi du véhicule','Si la compagnie active le partage de votre voyage, « Suivre mon car » apparaît dans votre billet. Seules les positions transmises par le véhicule sont affichées.']].map(([ico,t,c])=>`<article class="panel help-card"><span class="square-icon soft">${i(ico,23)}</span><h3>${t}</h3><p>${c}</p></article>`).join('')}</div><section class="contact-card"><div><h2>Parlons de votre voyage.</h2><p>La compagnie vous aide à préparer votre départ.</p></div>${cfg?.phone?`<a class="primary" href="tel:${e(cfg.phone.replace(/[^+\d]/g,''))}">${i('phone',18)} ${e(cfg.phone)}</a>`:''}<button class="secondary" data-go="requests">Écrire à la compagnie</button></section>`}
function helpPage(){shell(title('UNE QUESTION ?','Le voyage, en toute simplicité.')+helpContent(),'Aide')}
async function start(){booting=true;render();try{cfg=await api('/config');connected=true;write('config',cfg);if(token){try{me=await api('/me');write('profile',me,remember?localStorage:sessionStorage);await Promise.all([accountData(),loadOrders()])}catch(err){if(err.status!==401)notify(err.message,true)}}}catch(err){connected=false;notify(err.message,true)}finally{booting=false;render()}}
window.addEventListener('offline',()=>{connected=false;orders=storedTickets();render();notify('Les billets enregistrés restent accessibles dans Mes voyages.')});window.addEventListener('online',()=>start());window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(navigation.some(x=>x[0]===next)&&next!==page)go(next)});
window.addEventListener('focus',()=>{if(page==='tickets'&&token&&navigator.onLine)loadOrders()});
me=me||read('profile',null,sessionStorage);orders=storedTickets();page=navigation.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'home';start();
if(!native&&'serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
